from functools import wraps

def validate_positive(func):
    @wraps(func)
    def wrapper(*args):
        if any(a < 0 for a in args):
            raise ValueError('Args must be positive')
        return func(*args)
    return wrapper

@validate_positive
def add(a, b):
    return a + b

print(add(3, 5))
